BEGIN TRAN;
UPDATE Customers SET BusinessName = @NewName WHERE Id = @Id AND Code = @Code AND BusinessName = @ExpectedName;
IF @@ROWCOUNT <> 1 BEGIN ROLLBACK; THROW 50001, 'Aggiornamento non valido', 1; END;
COMMIT;

var list = values.ToList();
var counts = new Dictionary<int,int>();
foreach (var v in list) counts[v] = counts.GetValueOrDefault(v) + 1;
foreach (var v in list) if (counts[v] == 1) return v;
return null;
